import functools
import time

def retry(times=3, delay=0):
    if times < 1:
        raise ValueError("times 必须 >= 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_error = None
            for attempt in range(times):
                try:
                    return func(*args, **kwargs)
                except Exception as error:
                    last_error = error
                    if attempt < times - 1 and delay > 0:
                        time.sleep(delay)
            raise last_error

        return wrapper

    return decorator

